# Testo e scaletta visiva del video lungo (un'unica fonte per script.py e scenes.py)
# Caso 029: l'affare della collana (Versailles-Parigi 1784-1786) e il conte di Cagliostro (Palermo 1743 - San Leo 1795)
VS = "[Versailles|Versài]"; RO = "[Rohan|Roàn]"; JE = "[Jeanne|Giànn]"; JM = "[Jeanne de la Motte|Giànn de la Mòtt]"
RV = "[Rétaux de Villette|Retò de Vilètt]"; BO = "[Boehmer|Bòmer]"; BA = "[Bassenge|Bassànj]"; NI = "[Nicole|Nicòl]"
SC = [
 # 00 INTRO
 (0, f"Una sera d'agosto del 1784, nei giardini della reggia di {VS}, un cardinale di Francia incontra la regina Maria Antonietta. Lei gli dice poche parole, lui le crede. Ma quella donna non è la regina.", [('Una', 'cal:AGOSTO|1784'), ('giardini', 'grove:1'), ('cardinale', 'grove:2'), ('Ma', 'stamp:NON È LA REGINA')]),
 (0, f"È una giovane parigina scelta perché le somiglia. Dietro la messinscena c'è una nobile senza soldi, {JM}. E dietro la messinscena c'è anche un oggetto: una collana con quasi 650 diamanti.", [('giovane', 'i:lady_white|UNA SOSIA'), ('nobile', 'i:lady|' + 'JEANNE DE LA MOTTE'), ('oggetto', 'neck:0'), ('650', 'big:≈ 650|diamanti in una sola collana')]),
 (0, "Pochi mesi dopo quella collana sparisce, smontata pietra per pietra. I gioiellieri chiedono i soldi alla regina, che non l'ha mai ordinata. E il cardinale viene arrestato davanti a tutta la corte.", [('Pochi', 'neck:2'), ('gioiellieri', 'i:jeweler|I GIOIELLIERI'), ('regina', 'i:queen|«MAI ORDINATA»'), ('arrestato', 'i:mirrors|ARRESTATO A VERSAILLES')]),
 (0, "In questo fascicolo vedremo come nasce la truffa, la notte del boschetto, il processo, e il ruolo di un italiano finito anche lui alla Bastiglia: il conte di Cagliostro, nato a Palermo.", [('In', 'cover'), ('truffa', 'iii:quill|LE LETTERE|grove|IL BOSCHETTO|scales|IL PROCESSO'), ('italiano', 'map:Palermo|6|Palermo,Parigi|Palermo>Parigi'), ('Cagliostro', 't:L\'AFFARE DELLA COLLANA · 1784-1786')]),
 # 01 L'EPOCA E IL LUOGO
 (1, f"Siamo in Francia, negli anni Ottanta del Settecento. Il re è Luigi [XVI,|sedicesimo,] salito al trono nel 1774. La corte vive a {VS}, la grande reggia costruita fuori Parigi.", [('Siamo', 'tl:1772|LA COLLANA;1774|IL NUOVO RE;1784|IL BOSCHETTO;1785|L\'ARRESTO;1786|LA SENTENZA'), ('re', 'i:crown|LUIGI XVI'), ('1774', 'cal:IL NUOVO RE|1774'), ('reggia', 'map:Parigi|60|Parigi,Versailles')]),
 (1, f"A {VS} vivono e lavorano migliaia di persone: nobili, ministri, servitori, guardie. Tutto ruota intorno al re e alla regina. Essere ricevuti, essere guardati, essere esclusi: a corte è questo che decide una carriera.", [('vivono', 'crowd'), ('nobili', 'iii:crown|I NOBILI|ministry|I MINISTRI|guard2|LE GUARDIE'), ('Essere', 'h:Ricevuti\no *esclusi*')]),
 (1, "La regina è Maria Antonietta. È nata a Vienna, figlia dell'imperatrice Maria Teresa d'Austria, ed è arrivata in Francia da ragazza, per sposare l'erede al trono. Per molti francesi resta sempre l'austriaca.", [('regina', 'i:queen|MARIA ANTONIETTA'), ('Vienna', 'map:Vienna|10|Vienna,Parigi|Vienna>Parigi'), ("l'austriaca", 'stamp:L\'AUSTRIACA')]),
 (1, "Una parola sui soldi. In Francia si conta in lire tornesi, in francese livres. Non esiste un modo preciso per trasformare quelle cifre in euro di oggi: per questo, in questo video, le lasceremo così come sono.", [('soldi', 'i:livre|LIRE TORNESI'), ('euro', 'i:question|QUANTO IN EURO?'), ('preciso', 'big:Nessun cambio|preciso con gli euro di oggi'), ('lasceremo', 'stamp:CIFRE ORIGINALI')]),
 (1, f"E ora la collana. La sua storia comincia prima di tutto il resto, nel 1772. Il re di allora, Luigi [XV,|quindicesimo,] la ordina, secondo le ricostruzioni, come regalo per Madame [du Barry,|du Barrì,] la donna più vicina a lui negli ultimi anni.", [('collana', 'neck:0'), ('1772', 'cal:LA COLLANA|1772'), ('Luigi', 'i:crown|LUIGI XV'), ('du', 'i:lady|MADAME DU BARRY')]),
 (1, f"La preparano due gioiellieri di Parigi, Charles [Boehmer|Bòmer] e Paul [Bassenge.|Bassànj.] Ne esce un gioiello enorme, con quasi 650 diamanti.", [('gioiellieri', 'i:jeweler|BOEHMER E BASSENGE'), ('gioiello', 'neck:0'), ('650', 'big:≈ 650|diamanti')]),
 (1, "Ma nel 1774 Luigi [XV|quindicesimo] muore. Il nuovo re allontana dalla corte Madame [du Barry.|du Barrì.] E i due gioiellieri restano con in mano una collana che nessuno ha pagato, e che quasi nessuno al mondo può permettersi.", [('muore', 'cal:MUORE IL RE|1774'), ('allontana', 'i:lady|LONTANO DA CORTE'), ('gioiellieri', 'i:jeweler|UNA COLLANA SENZA COMPRATORE'), ('permettersi', 'stamp:INVENDUTA')]),
 (1, "Il prezzo, alla fine, supera il milione e mezzo di lire tornesi. Le fonti non danno tutte la stessa cifra: la reggia di Versailles e altre ricostruzioni parlano di un milione e seicentomila, altre di due milioni.", [('prezzo', 'i:livre|IL PREZZO'), ('fonti', 'ii:livre|1,6 MILIONI|livre|2 MILIONI'), ('seicentomila', 'big:1.600.000|lire tornesi · secondo più fonti'), ('due', 'stamp:FONTI NON CONCORDI')]),
 (1, "Facciamo un conto semplice: un milione e seicentomila diviso circa seicentocinquanta diamanti fa quasi duemilacinquecento lire tornesi a pietra, in media. Ogni singola pietra, da sola, è un piccolo patrimonio.", [('conto', 'h:Un *conto*'), ('diviso', 'big:≈ 2.460|lire tornesi a diamante · in media'), ('pietra', 'i:diamond|UNA SOLA PIETRA')]),
 (1, "I gioiellieri provano a venderla alla nuova regina. Le fonti non sono d'accordo sugli anni, ma su un punto sì: Maria Antonietta la rifiuta. Secondo le ricostruzioni avrebbe detto che alla Francia servivano più navi che collane.", [('provano', 'flow:I GIOIELLIERI>LA REGINA'), ('rifiuta', 'stamp:RIFIUTATA'), ('navi', 'ii:ship|LE NAVI|necklace|LA COLLANA')]),
 (1, "Così, all'inizio degli anni Ottanta, la collana più cara di Francia è ancora chiusa in un astuccio. Due gioiellieri che hanno investito una fortuna aspettano un compratore. Qualcuno, molto presto, troverà il modo di usarla.", [('collana', 'neck:0'), ('astuccio', 'i:jeweler|CHIUSA IN UN ASTUCCIO'), ('fortuna', 'i:moneybag|UNA FORTUNA FERMA'), ('Qualcuno', 'i:question|CHI LA USERÀ?')]),
 # 02 I PROTAGONISTI
 (2, "Prima di entrare nel piano, conosciamo i protagonisti. Al centro di tutto c'è lei, la collana: quasi seicentocinquanta diamanti, a più file, nelle mani di due gioiellieri parigini.", [('Prima', 'board:0'), ('collana', 'neck:0'), ('gioiellieri', 'board:1')]),
 (2, "Poi c'è la regina, Maria Antonietta. Sarà la grande assente di questa storia: il suo nome viene usato dall'inizio alla fine, ma lei, come stabiliranno i giudici, non sa niente.", [('regina', 'board:2'), ('assente', 'i:queen|LA GRANDE ASSENTE'), ('giudici', 'stamp:NON SA NIENTE')]),
 (2, f"Il terzo è il cardinale Louis de {RO}. È un principe e un cardinale. È Grande Elemosiniere del regno, cioè il capo del clero di corte. Ed è stato ambasciatore a Vienna.", [('terzo', 'board:3'), ('cardinale', 'i:cardinal|LOUIS DE ROHAN'), ('Elemosiniere', 'card:GRANDE ELEMOSINIERE|il capo del clero di corte|Versailles'), ('Vienna', 'map:Vienna|10|Parigi,Vienna')]),
 (2, f"Ma {RO} ha un problema: la regina non lo sopporta. Da ambasciatore, secondo le ricostruzioni, si era fatto una brutta fama a Vienna, e la madre di Maria Antonietta non lo stimava. A corte, la regina non gli rivolge la parola.", [('problema', 'i:queen|LA REGINA LO EVITA'), ('ambasciatore', 'i:ear|UNA BRUTTA FAMA'), ('madre', 'i:crown|MARIA TERESA'), ('parola', 'stamp:ESCLUSO')]),
 (2, "Per un uomo come lui, che secondo le ricostruzioni sogna di diventare ministro, è una condanna. Senza il favore della regina non si fa carriera. E il cardinale vorrebbe una cosa sopra tutte: tornare nelle sue grazie.", [('ministro', 'i:ministry|IL SOGNO: MINISTRO'), ('favore', 'h:Il *favore*\ndella regina'), ('grazie', 'stamp:IL SUO PUNTO DEBOLE')]),
 (2, f"La quarta è {JM}. Discende, per una linea illegittima, da un re di Francia del Cinquecento, Enrico secondo. Un nome nobile, insomma. Ma niente soldi.", [('quarta', 'board:4'), ('Discende', 'tl:1500|ENRICO II;1700|LA FAMIGLIA DECADE;1780|JEANNE A CORTE'), ('nobile', 'i:lady|UN NOME NOBILE'), ('soldi', 'i:box_empty|NIENTE SOLDI')]),
 (2, f"Cerca in ogni modo di farsi strada a corte, senza riuscirci. Ha sposato [Nicolas|Nicolà] de la Motte, che si fa chiamare conte senza esserlo davvero. Da qui, il nome di contessa de la Motte.", [('Cerca', 'i:door|UNA PORTA CHIUSA'), ('sposato', 'i:rings|IL MARITO'), ('conte', 'stamp:CONTE?'), ('contessa', 'h:La «*contessa*»\nde la Motte')]),
 (2, f"Il quinto è {RV}, un amico di {JE}. Ha una mano molto abile con la penna: sarà lui, come confesserà al processo, a scrivere le lettere false e a imitare la firma della regina.", [('quinto', 'board:5'), ('penna', 'i:quill|IL FALSARIO'), ('confesserà', 'stamp:CONFESSERÀ')]),
 (2, f"La sesta è una giovane parigina, {NI} Le Guay, che sarà conosciuta anche come [Nicole|Nicòl] d'Oliva. Non è una nobile e non conosce la corte. Ha una sola caratteristica che interessa: somiglia alla regina.", [('sesta', 'board:6'), ('parigina', 'i:lady_white|NICOLE LE GUAY'), ('somiglia', 'ii:lady_white|LEI|queen|LA REGINA')]),
 (2, "E infine c'è lui, l'italiano. Si fa chiamare conte Alessandro di Cagliostro, ma il suo vero nome, secondo le fonti, è Giuseppe Balsamo, nato a Palermo. Guaritore, alchimista, maestro di riti segreti. E amico del cardinale.", [('infine', 'board:7'), ('Cagliostro', 'card:ALESSANDRO DI CAGLIOSTRO|vero nome: Giuseppe Balsamo|Palermo'), ('Palermo', 'map:Palermo|30|Palermo'), ('amico', 'ii:cardinal|IL CARDINALE|flask|CAGLIOSTRO')]),
 (2, "Riassumiamo. Una collana che nessuno compra. Una regina che non c'entra. Un cardinale che vuole riconquistarla. Una nobile senza soldi. Un falsario, una sosia, e un italiano famoso. Adesso vediamo come si incastrano.", [('Riassumiamo', 'board:7'), ('falsario', 'iii:quill|IL FALSARIO|lady_white|LA SOSIA|flask|L\'ITALIANO'), ('incastrano', 'stamp:IL PIANO')]),
 # 03 IL PIANO
 (3, f"Le fonti non sono d'accordo su quando {JE} e il cardinale si conoscano, ma nella prima metà del 1784 lei è già entrata nella sua vita. E il cardinale comincia a darle soldi.", [('Le', 'ii:lady|JEANNE|cardinal|ROHAN'), ('1784', 'cal:IL PIANO|1784'), ('soldi', 'i:moneybag|I PRIMI SOLDI')]),
 (3, f"{JE} gli racconta una storia precisa: dice di essere diventata un'amica intima della regina. Una confidente. Una persona che entra nelle stanze private di Maria Antonietta e che può parlarle di lui.", [('racconta', 'i:lady|LA STORIA DI JEANNE'), ("un'amica", 'h:«Sono amica\ndella *regina*»'), ('stanze', 'i:door|LE STANZE PRIVATE'), ('parlarle', 'i:queen|UNA PAROLA PER LUI?')]),
 (3, "Non è vero. La regina non la riceve e non la conosce. Ma il cardinale non ha modo di verificarlo: a corte, lui è proprio l'uomo che Maria Antonietta non vuole vedere.", [('Non', 'stamp:FALSO'), ('riceve', 'i:queen|NON LA CONOSCE'), ('verificarlo', 'i:question|COME VERIFICARE?'), ('vedere', 'i:cardinal|ESCLUSO')]),
 (3, f"Ed ecco l'inganno più importante: le lettere. Il cardinale scrive alla regina, e {JE} gli porta le risposte. Sono biglietti con frasi gentili e la firma di Maria Antonietta.", [('lettere', 'i:quill|LE LETTERE'), ('scrive', 'flow:IL CARDINALE>LA «REGINA»'), ('biglietti', 'doc:BIGLIETTO|a nome della regina|frasi gentili|firma: imitata'), ('firma', 'stamp:FIRMA FALSA')]),
 (3, f"A scriverle è {RV}. Al processo ammetterà di aver scritto lui le lettere e di aver imitato la firma. Per il cardinale, invece, sono la prova che la regina ha cambiato idea su di lui.", [('scriverle', 'i:quill|RÉTAUX DE VILLETTE'), ('ammetterà', 'stamp:CONFESSIONE'), ('prova', 'i:cardinal|«MI HA PERDONATO»')]),
 (3, f"Le lettere chiedono anche soldi. La regina, spiega {JE}, vuole aiutare persone in difficoltà, ma non può farlo apertamente. Il cardinale presta somme importanti, convinto che siano per le opere di carità di Maria Antonietta.", [('soldi', 'i:moneybag|SOLDI «PER LA REGINA»'), ('apertamente', 'stamp:IN SEGRETO'), ('presta', 'flow:IL CARDINALE>JEANNE'), ('carità', 'i:hand|LA CARITÀ?')]),
 (3, "Ecco il meccanismo della truffa, detto in breve: una persona racconta di avere un accesso speciale a qualcuno di molto importante. Chi le crede paga per avvicinarsi. E più paga, più ha bisogno di continuare a crederci.", [('meccanismo', 'h:Il *meccanismo*'), ('accesso', 'flow:JEANNE>«LA REGINA»'), ('paga', 'i:livre|PIÙ PAGA...'), ('crederci', 'stamp:...PIÙ CI CREDE')]),
 (3, "Ma le lettere a un certo punto non bastano più. Il cardinale vuole di più: vuole vederla, vuole sentirsi dire di persona che il passato è dimenticato. Per il piano è il momento più pericoloso.", [('lettere', 'i:quill|NON BASTANO PIÙ'), ('vederla', 'i:eye|VUOLE VEDERLA'), ('pericoloso', 'stamp:IL RISCHIO')]),
 (3, f"Come si fa a far incontrare un uomo con una regina che non sa niente? La risposta di {JE} e dei suoi complici è semplice e audace: una regina falsa, di notte, nei giardini di {VS}.", [('Come', 'i:question|COME?'), ('regina', 'ii:queen|LA REGINA VERA|lady_white|LA REGINA FALSA'), ('giardini', 'grove:0')]),
 # 04 LA NOTTE DEL BOSCHETTO
 (4, f"Ed eccoci alla scena più famosa di tutta la storia. Agosto 1784, giardini di {VS}. Per la reggia di Versailles è il giorno 11 agosto. È notte, e nel parco ci sono boschetti, siepi alte, viali bui.", [('scena', 'grove:0'), ('1784', 'cal:IL BOSCHETTO|AGOSTO 1784'), ('giorno', 'cal:SECONDO LA REGGIA|11 AGOSTO'), ('notte', 'grove:0')]),
 (4, "Le fonti chiamano quel luogo in modi diversi: boschetto della regina, boschetto di Venere. È un angolo appartato del parco, circondato da alberi, dove al buio è difficile riconoscere un volto.", [('fonti', 'ii:grove|«DELLA REGINA»|grove|«DI VENERE»'), ('appartato', 'grove:0'), ('buio', 'h:Al buio,\nun volto *qualsiasi*')]),
 (4, f"Il cardinale arriva all'appuntamento, convinto di incontrare Maria Antonietta. {JE} è lì vicino, a regia di tutto. Non lontano c'è anche {RV}.", [('cardinale', 'grove:2'), ('Jeanne', 'i:lady|LA REGISTA'), ('Rétaux', 'i:quill|IL COMPLICE')]),
 (4, f"Dal buio esce una donna, vestita di bianco secondo le ricostruzioni. È {NI}, la giovane parigina scelta per la somiglianza. Per quella sera è stata preparata e istruita.", [('buio', 'grove:3'), ('bianco', 'i:lady_white|VESTITA DI BIANCO'), ('somiglianza', 'ii:lady_white|NICOLE|queen|LA REGINA'), ('istruita', 'stamp:UNA SOSIA')]),
 (4, f"Secondo le ricostruzioni l'incontro dura pochi istanti. La donna gli dice poche parole: secondo le ricostruzioni, gli fa capire che il passato è dimenticato. Per {RO} è il momento che aspettava da anni.", [("l'incontro", 'clock:23|POCHI ISTANTI'), ('parole', 'h:«Il passato\nè *dimenticato*»'), ('anni', 'i:cardinal|IL GIORNO CHE ASPETTAVA')]),
 (4, "C'è anche una rosa. Ma qui le fonti non coincidono: per alcune è la donna a dare una rosa al cardinale, per altre è lui a offrirla a lei. Di sicuro, quella rosa diventerà un simbolo dell'intera storia.", [('rosa', 'i:rose|LA ROSA'), ('fonti', 'ii:lady_white|LEI A LUI?|cardinal|LUI A LEI?'), ('simbolo', 'stamp:FONTI NON CONCORDI')]),
 (4, "Poi la donna sparisce tra gli alberi. Il cardinale resta lì, nel buio, convinto di aver parlato con la regina di Francia.", [('Poi', 'grove:1'), ('sparisce', 'i:lady_white|SPARISCE'), ('convinto', 'i:cardinal|«HO PARLATO CON LA REGINA»')]),
 (4, f"Da quella sera, il cardinale non ha più dubbi. Le lettere sono vere, l'amicizia di {JE} con la regina è vera, e lui è tornato nelle grazie di Maria Antonietta. Il terreno, adesso, è pronto per il colpo grosso.", [('dubbi', 'stamp:NESSUN DUBBIO'), ('lettere', 'iii:quill|LE LETTERE|lady|L\'AMICA|queen|LA REGINA'), ('colpo', 'neck:0')]),
 (4, "Facciamo il punto con la nostra scheda. Una regina che non sa niente. Lettere false. Soldi prestati per una carità che non esiste. E un incontro notturno con una sosia. Manca solo l'oggetto del desiderio: la collana.", [('punto', 'board:6'), ('Lettere', 'iii:quill|LETTERE FALSE|moneybag|SOLDI|lady_white|LA SOSIA'), ('collana', 'neck:0')]),
 (4, "Se questa storia ti sta piacendo, iscriviti a Fascicolo Italia: ogni giorno un nuovo caso. E adesso, la collana.", [('Se', 'subscribe'), ('collana', 'neck:0')]),
 # 05 LA COLLANA
 (5, f"Nel frattempo i gioiellieri {BO} e {BA} non hanno ancora venduto la collana. E secondo le ricostruzioni, è proprio {JE} a sentirne parlare e a vedere l'occasione: il cardinale è pronto a tutto per la regina.", [('gioiellieri', 'i:jeweler|ANCORA INVENDUTA'), ("l'occasione", 'h:L\'*occasione*'), ('pronto', 'ii:cardinal|IL CARDINALE|necklace|LA COLLANA')]),
 (5, "A gennaio del 1785 arriva la proposta. La regina, spiega [Jeanne,|Giànn,] desidera la collana. Ma secondo le ricostruzioni vuole comprarla senza che si sappia, e chiede al cardinale di fare da intermediario.", [('gennaio', 'cal:LA PROPOSTA|GENNAIO 1785'), ('desidera', 'i:queen|«LA DESIDERA»'), ('sappia', 'stamp:IN SEGRETO'), ('intermediario', 'i:cardinal|L\'INTERMEDIARIO')]),
 (5, "Per il cardinale è la prova definitiva: la regina si fida di lui al punto di affidargli un affare delicato. Accetta. E tratta con i gioiellieri il prezzo e le condizioni.", [('prova', 'i:cardinal|«SI FIDA DI ME»'), ('Accetta', 'stamp:ACCETTA'), ('gioiellieri', 'flow:IL CARDINALE>I GIOIELLIERI')]),
 (5, "Le condizioni sono queste: la collana sarà pagata a rate, in circa due anni. Il cardinale si impegna con i gioiellieri. E mostra loro le condizioni approvate, dice lui, dalla regina: un foglio scritto e firmato, anche questo, dal falsario.", [('rate', 'doc:CONDIZIONI|la collana · a rate|circa due anni|trattate dal cardinale'), ('impegna', 'i:signature|L\'IMPEGNO'), ('foglio', 'i:quill|«APPROVATO»'), ('falsario', 'stamp:FALSO')]),
 (5, "Le fonti non concordano sul prezzo finale: la reggia di Versailles e altre ricostruzioni parlano di un milione e seicentomila lire tornesi, altre di due milioni. In ogni caso, una delle cifre più alte mai chieste per un gioiello.", [('prezzo', 'ii:livre|1,6 MILIONI|livre|2 MILIONI'), ('cifre', 'big:1.600.000|lire tornesi · secondo più fonti'), ('gioiello', 'neck:0')]),
 (5, "E poi la consegna. Anche qui le date non coincidono: per alcune fonti il 25 gennaio, per la reggia di Versailles il primo febbraio 1785. I gioiellieri portano la collana al cardinale.", [('consegna', 'i:jeweler|LA CONSEGNA'), ('25', 'ii:calendar_x|25 GENNAIO?|calendar_x|1 FEBBRAIO?'), ('febbraio', 'cal:LA CONSEGNA|1 FEBBRAIO 1785'), ('cardinale', 'flow:I GIOIELLIERI>IL CARDINALE')]),
 (5, f"Il cardinale la porta a casa di {JE}. Lì, secondo le ricostruzioni, la affida a un uomo che crede un messaggero della regina, incaricato di portarla a {VS}. In realtà, è un complice.", [('porta', 'i:house|A CASA DI JEANNE'), ('messaggero', 'i:envelope|«UN MESSAGGERO DELLA REGINA»'), ('complice', 'stamp:UN COMPLICE')]),
 (5, "In quel momento la collana esce per sempre dalla storia ufficiale. Il cardinale torna a casa felice: ha fatto un favore alla regina. I gioiellieri tornano in bottega soddisfatti: hanno finalmente venduto.", [('esce', 'neck:1'), ('felice', 'i:cardinal|FELICE'), ('gioiellieri', 'i:jeweler|«FINALMENTE VENDUTA»')]),
 (5, "Fermiamoci un attimo sulle date. Dalla notte del boschetto, ad agosto 1784, alla consegna della collana, tra fine gennaio e inizio febbraio 1785, passano meno di sei mesi. Il piano corre veloce.", [('date', 'tl:AGO 1784|IL BOSCHETTO;GEN 1785|LA PROPOSTA;FEB 1785|LA CONSEGNA'), ('sei', 'big:< 6 mesi|dal boschetto alla collana')]),
 # 06 I DIAMANTI SPARISCONO
 (6, "Ma dove finisce la collana? Non a Versailles. Le fonti concordano su un punto: viene smontata. I diamanti vengono staccati uno a uno dalla montatura.", [('dove', 'i:question|DOVE FINISCE?'), ('smontata', 'neck:1'), ('diamanti', 'i:diamonds|PIETRA PER PIETRA')]),
 (6, "Una collana intera, famosa, è impossibile da vendere senza farsi scoprire. Ma i diamanti sciolti sono un'altra cosa: si possono vendere uno alla volta, in posti diversi, senza attirare troppo l'attenzione.", [('intera', 'neck:0'), ('impossibile', 'stamp:TROPPO FAMOSA'), ('sciolti', 'i:diamonds|DIAMANTI SCIOLTI')]),
 (6, f"Parte delle pietre viene venduta a Parigi. E molte, secondo le fonti, le porta a Londra il marito di {JE}, [Nicolas|Nicolà] de la Motte, che le vende ai gioiellieri inglesi.", [('Parigi', 'map:Parigi|30|Parigi,Londra'), ('Londra', 'map:Londra|30|Parigi,Londra|Parigi>Londra'), ('inglesi', 'i:shop|I GIOIELLIERI DI LONDRA')]),
 (6, "Le ricostruzioni non sono d'accordo sui dettagli di queste vendite: chi vende cosa, dove, a quale prezzo. Di sicuro, una parte del valore della collana si trasforma in fretta in contanti.", [('ricostruzioni', 'stamp:FONTI NON CONCORDI'), ('vende', 'iii:diamond|CHI?|globe2|DOVE?|livre|QUANTO?'), ('contanti', 'i:money|IN CONTANTI')]),
 (6, "Intanto si avvicina la scadenza della prima rata. I gioiellieri aspettano i soldi. Il cardinale aspetta i soldi della regina per pagarli. E la regina, che non sa niente, non manda niente.", [('scadenza', 'cal:LA PRIMA RATA|ESTATE 1785'), ('gioiellieri', 'iii:jeweler|ASPETTANO|cardinal|ASPETTA|queen|NON SA')]),
 (6, f"{JE} prova a guadagnare tempo, con nuove scuse e nuove promesse. Ma i gioiellieri hanno messo una fortuna in quella collana, e non possono aspettare all'infinito.", [('tempo', 'i:hourglass|GUADAGNARE TEMPO'), ('scuse', 'h:Nuove *scuse*'), ('fortuna', 'i:moneybag|UNA FORTUNA IN SOSPESO')]),
 (6, f"Così, nell'estate del 1785, {BO} fa la cosa più naturale: si rivolge direttamente alla regina e le scrive un biglietto. La reggia di Versailles lo data al 12 luglio.", [("nell'estate", 'cal:BOEHMER SCRIVE|12 LUGLIO 1785'), ('regina', 'flow:IL GIOIELLIERE>LA REGINA'), ('biglietto', 'doc:BIGLIETTO DEL GIOIELLIERE|alla regina|sulla collana|12 luglio 1785')]),
 (6, "La regina non capisce di cosa parli e, secondo la reggia di Versailles, distrugge il biglietto. Ad agosto, il gioielliere si rivolge a una delle donne di fiducia di Maria Antonietta, Madame [Campan.|Campàn.]", [('capisce', 'i:queen|«QUALE ACQUISTO?»'), ('distrugge', 'stamp:DISTRUTTO'), ('Campan', 'i:lady|MADAME CAMPAN')]),
 (6, "Ed è così che, finalmente, la verità arriva alla regina. Maria Antonietta scopre che qualcuno ha comprato a suo nome la collana che lei aveva rifiutato. Che c'è un foglio con la sua firma. E che la firma non è sua.", [('verità', 'i:queen|LA VERITÀ'), ('comprato', 'neck:2'), ('foglio', 'doc:CONDIZIONI|la collana · a rate|«approvato»|firma: NON È SUA'), ('sua', 'stamp:FIRMA FALSA')]),
 (6, "Per la regina è un'umiliazione. Il suo nome è stato usato da sconosciuti per un affare da più di un milione. E l'uomo che ha trattato tutto è proprio il cardinale che lei detesta.", [("un'umiliazione", 'h:Un\'*umiliazione*'), ('milione', 'big:> 1 milione|di lire tornesi · a suo nome'), ('cardinale', 'i:cardinal|IL CARDINALE CHE DETESTA')]),
 # 07 L'ARRESTO
 (7, f"15 agosto 1785. È il giorno dell'Assunzione, una delle feste più importanti dell'anno. A {VS} il cardinale di {RO}, Grande Elemosiniere, si prepara a celebrare la messa nella cappella reale.", [('15', 'cal:L\'ASSUNZIONE|15 AGOSTO 1785'), ('feste', 'i:bell|LA FESTA'), ('messa', 'i:cardinal|PRONTO PER LA MESSA')]),
 (7, "Prima della funzione viene chiamato negli appartamenti del re. Lì trova Luigi [XVI,|sedicesimo,] la regina e alcuni ministri. Gli chiedono conto della collana.", [('chiamato', 'i:door|NEGLI APPARTAMENTI DEL RE'), ('regina', 'iii:crown|IL RE|queen|LA REGINA|ministry|I MINISTRI'), ('collana', 'neck:2')]),
 (7, "Il cardinale capisce in quel momento di essere stato ingannato. Prova a spiegare: le lettere, l'incontro, la mediazione di una donna che diceva di conoscere la regina. Ma la regina quelle lettere non le ha mai scritte.", [('ingannato', 'stamp:INGANNATO'), ('spiegare', 'iii:quill|LE LETTERE|grove|IL BOSCHETTO|lady|JEANNE'), ('mai', 'i:queen|«NON SONO MIE»')]),
 (7, "Poco dopo, uscendo, il cardinale viene arrestato nella Galleria degli Specchi, il cuore della reggia. Un principe della Chiesa, arrestato nel giorno della festa.", [('arrestato', 'i:mirrors|LA GALLERIA DEGLI SPECCHI'), ('principe', 'i:cardinal|UN PRINCIPE DELLA CHIESA'), ('festa', 'stamp:ARRESTATO')]),
 (7, "La notizia fa scandalo. Il cardinale viene portato alla Bastiglia, la prigione-fortezza di Parigi. Ci resterà per mesi.", [('notizia', 'i:newspaper|LO SCANDALO'), ('Bastiglia', 'i:fortress|LA BASTIGLIA')]),
 (7, f"Pochi giorni dopo viene arrestata anche {JM}. Più tardi finiscono in carcere anche {RV} e {NI}, la donna del boschetto. E con loro, il conte di Cagliostro.", [('Pochi', 'i:lady|JEANNE ARRESTATA'), ('Rétaux', 'iii:quill|RÉTAUX|lady_white|NICOLE|flask|CAGLIOSTRO'), ('Cagliostro', 'i:handcuffs|ANCHE CAGLIOSTRO')]),
 (7, f"Perché anche Cagliostro? Perché è un amico del cardinale. Il suo ruolo nella truffa, secondo diverse fonti, è molto dubbio, e le versioni non coincidono. Ma il suo nome, così famoso, attira ancora di più l'attenzione.", [('Perché', 'i:question|PERCHÉ LUI?'), ('amico', 'ii:cardinal|IL CARDINALE|flask|L\'AMICO'), ('dubbio', 'stamp:RUOLO DUBBIO')]),
 (7, f"Manca qualcuno all'appello: [Nicolas|Nicolà] de la Motte, il marito di {JE}. È a Londra, insieme a molti dei diamanti. E a Londra resterà.", [('Manca', 'i:question|CHI MANCA?'), ('Londra', 'map:Londra|30|Parigi,Londra'), ('resterà', 'i:diamonds|CON I DIAMANTI')]),
 (7, "E la collana? Non c'è più. Non c'è un oggetto da restituire, non c'è un gioiello da mostrare ai giudici. Ci sono solo lettere false, un contratto, testimonianze. E un enorme debito con i gioiellieri.", [('collana', 'neck:2'), ('oggetto', 'stamp:NIENTE DA RESTITUIRE'), ('lettere', 'iii:quill|LETTERE|signature|UN CONTRATTO|witness|TESTIMONI'), ('debito', 'i:moneybag|IL DEBITO')]),
 (7, "Un piccolo riepilogo per chi ci raggiunge adesso. Agosto 1784: la notte del boschetto. Inizio 1785: la collana consegnata e smontata. 15 agosto 1785: l'arresto a Versailles. Adesso tocca ai giudici.", [('riepilogo', 'tl:AGO 1784|IL BOSCHETTO;FEB 1785|LA COLLANA;AGO 1785|L\'ARRESTO;1786|IL PROCESSO'), ('giudici', 'i:court|I GIUDICI')]),
 # 08 IL PROCESSO
 (8, f"Il caso viene giudicato dal Parlamento di Parigi. Attenzione alla parola: nella Francia di allora i Parlamenti non sono assemblee elette, ma grandi tribunali. E quello di Parigi è il più importante del regno.", [('giudicato', 'court:IL PARLAMENTO DI PARIGI'), ('Parlamenti', 'h:Parlamento\n= *tribunale*'), ('Parigi', 'map:Parigi|60|Parigi,Versailles')]),
 (8, f"Per la regina il processo è l'occasione di dimostrare davanti a tutti di non avere niente a che fare con la collana, né con appuntamenti segreti nei giardini.", [('re', 'ii:crown|IL RE|queen|LA REGINA'), ('dimostrare', 'h:«Io non\nc\'*entro*»'), ('segreti', 'grove:0')]),
 (8, f"Ma un processo pubblico ha le sue regole. Si leggono le lettere, si ascoltano gli imputati, si confrontano le versioni. E per mesi Parigi non parla d'altro.", [('pubblico', 'i:court|UN PROCESSO PUBBLICO'), ('lettere', 'iii:quill|LE LETTERE|witness|I TESTIMONI|scales|LE VERSIONI'), ('Parigi', 'crowd')]),
 (8, f"{RV} ammette di aver scritto le lettere e di aver imitato la firma della regina. È la confessione che toglie ogni dubbio: quelle lettere non sono mai uscite dalle stanze di Maria Antonietta.", [('ammette', 'i:quill|LA CONFESSIONE'), ('firma', 'stamp:FIRMA IMITATA'), ('stanze', 'i:queen|MAI SCRITTE DA LEI')]),
 (8, f"{NI} racconta la sua parte nella scena del boschetto. E il cardinale si presenta per quello che, secondo i giudici, è stato davvero: la vittima di un inganno.", [('racconta', 'i:lady_white|LA SOSIA PARLA'), ('boschetto', 'grove:3'), ('vittima', 'i:cardinal|«SONO STATO INGANNATO»')]),
 (8, f"Per {JM}, invece, il quadro è pesante: è lei ad aver tessuto la storia dell'amicizia con la regina, ed è nelle sue mani che è finita la collana.", [('Per', 'i:lady|JEANNE DE LA MOTTE'), ("dell'amicizia", 'h:L\'*amicizia*\ninventata'), ('mani', 'neck:1')]),
 (8, "31 maggio 1786. Il Parlamento di Parigi pronuncia la sentenza. Dall'arresto del cardinale sono passati duecentottantanove giorni: più di nove mesi.", [('31', 'cal:LA SENTENZA|31 MAGGIO 1786'), ('Parlamento', 'court:LA SENTENZA'), ('duecentottantanove', 'big:289 giorni|dall\'arresto alla sentenza')]),
 (8, f"Il cardinale di {RO} viene assolto. Per i giudici è stato ingannato, non ha commesso un reato. Per molti parigini, che stanno dalla sua parte, è quasi un trionfo. Per la regina, un colpo durissimo.", [('assolto', 'stamp:ASSOLTO'), ('ingannato', 'i:cardinal|INGANNATO, NON COLPEVOLE'), ('trionfo', 'crowd'), ('regina', 'i:queen|UN COLPO DURISSIMO')]),
 (8, f"Anche {NI}, la donna del boschetto, viene assolta. E viene assolto il conte di Cagliostro: dalle prove non risulta che abbia avuto parte nella truffa.", [('assolta', 'ii:lady_white|NICOLE · ASSOLTA|flask|CAGLIOSTRO · ASSOLTO'), ('prove', 'stamp:ASSOLTI')]),
 (8, f"{RV}, il falsario, viene condannato al bando: deve lasciare la Francia per sempre.", [('falsario', 'i:quill|IL FALSARIO'), ('bando', 'stamp:BANDITO DALLA FRANCIA')]),
 (8, f"La condanna più dura è per {JM}: pene corporali e carcere a vita, alla [Salpêtrière|Salpetrièr] di Parigi. Suo marito [Nicolas,|Nicolà,] rimasto a Londra, non viene mai preso.", [('condanna', 'i:gavel|LA CONDANNA PIÙ DURA'), ('vita', 'i:prison|CARCERE A VITA'), ('Nicolas', 'map:Londra|30|Parigi,Londra'), ('preso', 'stamp:MAI PRESO')]),
 (8, f"Riepiloghiamo le sentenze. Assolti: il cardinale, la sosia, Cagliostro. Bandito: il falsario. Condannata: {JE}. E la regina, che non era imputata, esce dal processo come la vera perdente.", [('Riepiloghiamo', 'board:7'), ('Assolti', 'iii:cardinal|ASSOLTO|lady_white|ASSOLTA|flask|ASSOLTO'), ('regina', 'i:queen|LA VERA PERDENTE')]),
 (8, f"Perché perdente? Perché l'assoluzione del cardinale dice, in fondo, che era normale credere a una regina che dà appuntamenti di notte e compra gioielli di nascosto. Per molti, se tutti ci hanno creduto, forse un po' di vero c'era.", [('Perché', 'i:question|PERCHÉ PERDENTE?'), ('normale', 'h:«Era *normale*\ncrederci»'), ('vero', 'stamp:IL SOSPETTO')]),
 # 09 L'ITALIANO
 (9, "Ora fermiamoci sull'unico italiano di questa storia, il conte di Cagliostro. Chi era davvero?", [('italiano', 'map:Palermo|30|Palermo'), ('davvero', 'i:question|CHI ERA?')]),
 (9, "Secondo le fonti, il suo vero nome è Giuseppe Balsamo. Nasce a Palermo nel 1743, nel giugno, anche se le fonti non sono d'accordo sul giorno.", [('nome', 'card:GIUSEPPE BALSAMO|nato a Palermo|1743'), ('Palermo', 'map:Palermo|30|Palermo,Roma'), ('1743', 'cal:PALERMO|1743'), ('giorno', 'stamp:GIORNO NON CONCORDE')]),
 (9, "Da ragazzo viene affidato a dei religiosi, ma la vita del convento non fa per lui. Le fonti raccontano i suoi primi guai a Palermo, tra raggiri e piccoli imbrogli, e poi la fuga dalla città.", [('religiosi', 'i:convent|IL CONVENTO'), ('guai', 'i:question|I PRIMI GUAI'), ('fuga', 'map:Palermo|30|Palermo,Roma|Palermo>Roma')]),
 (9, "Nel 1768, a Roma, sposa una ragazza romana, Lorenza Feliciani, che si farà chiamare Serafina. Insieme cominciano a viaggiare per l'Europa.", [('1768', 'cal:ROMA|1768'), ('Lorenza', 'i:rings|LORENZA FELICIANI'), ('viaggiare', 'map:Roma|5|Roma,Londra,Parigi,Vienna')]),
 (9, "Lungo la strada cambia nome. Diventa il conte Alessandro di Cagliostro, un titolo che non gli spetta. Si presenta come medico, alchimista, uomo che conosce segreti antichi.", [('nome', 'flow:GIUSEPPE BALSAMO>CONTE DI CAGLIOSTRO'), ('titolo', 'stamp:TITOLO INVENTATO'), ('medico', 'iii:flask|ALCHIMISTA|tubes|«MEDICO»|oldbook|SEGRETI')]),
 (9, "Vende rimedi e pozioni, promette guarigioni. Per molti è un ciarlatano, e i suoi rimedi non hanno nulla di miracoloso. Ma la sua fama cresce lo stesso.", [('rimedi', 'i:bottle|RIMEDI E POZIONI'), ('ciarlatano', 'i:question|UN CIARLATANO?'), ('fama', 'stamp:LA FAMA CRESCE')]),
 (9, "Entra nella massoneria a Londra, negli anni Settanta, e poi fonda un suo rito, che chiama egiziano. Lui ne è il capo, il Gran Cofto. Le sue logge attirano nobili e persone ricche in mezza Europa.", [('massoneria', 'map:Londra|30|Londra'), ('egiziano', 'i:temple|IL RITO «EGIZIANO»'), ('Cofto', 'h:Il Gran *Cofto*'), ('logge', 'crowd')]),
 (9, f"Secondo le ricostruzioni è a Strasburgo, all'inizio degli anni Ottanta, che conosce il cardinale di {RO}, che diventa suo protettore. Poi lo segue a Parigi, dove diventa una celebrità.", [('Strasburgo', 'map:Strasburgo|30|Strasburgo,Parigi|Strasburgo>Parigi'), ('protettore', 'ii:cardinal|IL CARDINALE|flask|CAGLIOSTRO'), ('Parigi', 'i:eiffel|PARIGI')]),
 (9, "Ed è a Parigi che lo raggiunge l'affare della collana. Arrestato, resta alla Bastiglia per circa nove mesi. Poi l'assoluzione, il 31 maggio 1786.", [('collana', 'neck:2'), ('Bastiglia', 'i:fortress|9 MESI ALLA BASTIGLIA'), ("l'assoluzione", 'cal:ASSOLTO|31 MAGGIO 1786')]),
 (9, "Ma l'assoluzione non basta. Il re lo espelle dalla Francia. Cagliostro e la moglie tornano a Londra.", [('espelle', 'stamp:ESPULSO DALLA FRANCIA'), ('Londra', 'map:Londra|20|Parigi,Londra|Parigi>Londra')]),
 (9, "Intanto qualcuno indaga su chi sia davvero. Lo scrittore tedesco Goethe, in viaggio in Sicilia, va a Palermo a cercare la famiglia Balsamo. Le fonti non concordano sull'anno: 1787 o 1788.", [('indaga', 'i:magnifier|CHI È DAVVERO?'), ('Goethe', 'i:oldbook|GOETHE IN SICILIA'), ('Palermo', 'map:Palermo|30|Palermo,Roma'), ('1787', 'stamp:1787 O 1788?')]),
 (9, "Trova la madre e la sorella di Giuseppe Balsamo, che vivono in condizioni modeste e non hanno più sue notizie da tempo. La leggenda del conte misterioso comincia a incrinarsi.", [('madre', 'ii:lady|LA MADRE|lady|LA SORELLA'), ('modeste', 'i:house|UNA CASA MODESTA'), ('leggenda', 'stamp:LA LEGGENDA SI INCRINA')]),
 (9, "Nel 1789 Cagliostro torna a Roma, nella città della moglie. È una scelta pericolosa: nello Stato della Chiesa la massoneria è proibita.", [('1789', 'cal:ROMA|1789'), ('Roma', 'map:Roma|30|Londra,Roma|Londra>Roma'), ('proibita', 'stamp:PROIBITA')]),
 (9, "A dicembre del 1789 viene arrestato dal tribunale dell'Inquisizione. Le accuse riguardano la massoneria, l'eresia, le pratiche magiche. Anche la moglie finisce nelle mani dell'Inquisizione, e verrà chiusa in un convento.", [('dicembre', 'cal:ARRESTATO A ROMA|DICEMBRE 1789'), ("dell'Inquisizione", 'court:L\'INQUISIZIONE'), ('moglie', 'i:convent|LA MOGLIE IN CONVENTO')]),
 (9, "Nel 1791 arriva la condanna: carcere a vita. Le fonti non sono d'accordo su un punto: per alcune era stato condannato prima a morte, con la pena trasformata dal papa in carcere a vita.", [('1791', 'cal:LA CONDANNA|1791'), ('vita', 'i:prison|CARCERE A VITA'), ('papa', 'stamp:VERSIONI NON CONCORDI')]),
 (9, "Viene rinchiuso nella fortezza di San Leo, su una rupe dell'Appennino, oggi in provincia di Rimini. Lì muore il 26 agosto 1795, a cinquantadue anni, senza essere mai più uscito.", [('fortezza', 'i:fortress|LA ROCCA DI SAN LEO'), ('San', 'map:San Leo|60|San Leo,Roma'), ('26', 'cal:SAN LEO|26 AGOSTO 1795'), ('mai', 'stamp:MAI PIÙ USCITO')]),
 (9, "Un conto sulla sua vita: da Palermo a Parigi, in linea d'aria, ci sono quasi millecinquecento chilometri. Ne ha percorsi molti di più, tra Londra, Strasburgo, Parigi e Roma. Ed è finito in una cella, su una rupe dell'Appennino.", [('conto', 'map:Palermo|6|Palermo,Parigi|Palermo>Parigi'), ('millecinquecento', 'big:≈ 1.500 km|Palermo - Parigi · in linea d\'aria'), ('cella', 'i:cell|SAN LEO')]),
 # 10 COSA È SUCCESSO DOPO
 (10, f"E gli altri? Il cardinale di {RO} è assolto, ma il re non lo perdona. Gli toglie le cariche e lo manda in esilio lontano da corte, nell'abbazia di [La Chaise-Dieu,|La Scès-Diö,] in Alvernia.", [('cardinale', 'i:cardinal|ASSOLTO MA ESILIATO'), ('cariche', 'stamp:SENZA CARICHE'), ("nell'abbazia", 'map:La Chaise-Dieu|40|Parigi,La Chaise-Dieu|Parigi>La Chaise-Dieu')]),
 (10, f"{JE} non resta in carcere a lungo. Poco tempo dopo la condanna riesce a fuggire dalla Salpêtrière, e raggiunge Londra.", [('carcere', 'i:prison|LA SALPÊTRIÈRE'), ('fuggire', 'stamp:FUGGITA'), ('Londra', 'map:Londra|20|Parigi,Londra|Parigi>Londra')]),
 (10, "A Londra pubblica le sue memorie. Nel 1789 escono i suoi scritti, con la sua versione dei fatti, in cui il nome della regina torna di nuovo al centro. Una versione mai provata, ma letta e ripetuta.", [('memorie', 'i:oldbook|LE MEMORIE DI JEANNE'), ('1789', 'cal:LE MEMORIE|1789'), ('provata', 'stamp:MAI PROVATA')]),
 (10, f"E i gioiellieri {BO} e {BA}? Hanno consegnato una collana enorme e non sono stati pagati. Le fonti parlano di gravi difficoltà, fino al fallimento per alcune. Sono le vittime economiche dirette della truffa.", [('gioiellieri', 'i:jeweler|I GIOIELLIERI'), ('pagati', 'stamp:MAI PAGATI'), ('fallimento', 'i:moneybag|LE DIFFICOLTÀ')]),
 (10, "E i diamanti? Smontati e venduti, si disperdono tra Parigi e Londra. Della collana, come oggetto, non resta niente. Oggi ne esistono solo disegni e ricostruzioni.", [('diamanti', 'i:diamonds|DISPERSI'), ('niente', 'neck:2'), ('ricostruzioni', 'stamp:SOLO RICOSTRUZIONI')]),
 (10, "Ma la conseguenza più grande non riguarda nessuno degli imputati. Riguarda la persona che non era nemmeno sotto processo: Maria Antonietta.", [('conseguenza', 'h:La conseguenza\npiù *grande*'), ('processo', 'i:queen|NON ERA IMPUTATA')]),
 (10, "La regina era innocente, e i giudici non l'hanno mai accusata di niente. Eppure, come scrive la stessa reggia di Versailles, la sua reputazione ne esce macchiata e non si riprenderà più.", [('innocente', 'stamp:INNOCENTE'), ('Versailles', 'i:museum|LA REGGIA DI VERSAILLES'), ('reputazione', 'i:queen|UNA REPUTAZIONE MACCHIATA')]),
 (10, "Per molti francesi la storia della collana diventa il simbolo di una corte lontana, che spende cifre enormi mentre il paese fatica. Che la regina non abbia mai voluto quella collana, a quel punto, conta poco.", [('simbolo', 'h:Un *simbolo*'), ('cifre', 'ii:necklace|LA COLLANA|livre|LE SPESE'), ('poco', 'stamp:CONTA POCO')]),
 (10, "Tre anni dopo la sentenza, nel luglio del 1789, a Parigi viene presa la Bastiglia, la prigione dove erano stati chiusi il cardinale e Cagliostro. Comincia la Rivoluzione francese.", [('Tre', 'big:3 anni|dalla sentenza alla Rivoluzione'), ('Bastiglia', 'i:fortress|LUGLIO 1789'), ('Rivoluzione', 'cal:LA RIVOLUZIONE|1789')]),
 (10, "Nel 1793 Maria Antonietta viene processata dal tribunale rivoluzionario e giustiziata. La collana non è la causa della Rivoluzione, ma molti storici la ricordano come uno dei colpi che hanno distrutto l'immagine della monarchia.", [('1793', 'cal:LA REGINA|1793'), ('collana', 'neck:2'), ('monarchia', 'i:crown|L\'IMMAGINE DELLA MONARCHIA')]),
 (10, "Riepilogo per chi entra adesso. 1784: il boschetto. 1785: la collana sparisce, il cardinale arrestato. 1786: assolti cardinale, sosia e Cagliostro, condannata Jeanne. 1789: la Rivoluzione. 1795: Cagliostro muore a San Leo.", [('Riepilogo', 'tl:1784|BOSCHETTO;1785|ARRESTO;1786|SENTENZA;1789|RIVOLUZIONE;1795|SAN LEO'), ('1795', 'i:fortress|SAN LEO · 1795')]),
 # 11 LE DOMANDE APERTE
 (11, "Come in ogni grande caso, restano domande senza una risposta sicura. E punti su cui le fonti raccontano versioni diverse. Vediamoli uno per uno.", [('domande', 'h:Le domande\n*aperte*'), ('versioni', 'stamp:VERSIONI DIVERSE')]),
 (11, "Primo: il prezzo. Un milione e seicentomila lire tornesi per la reggia di Versailles e per altre fonti, due milioni per altre ancora. Forse perché si confondono il prezzo iniziale e quello trattato alla fine.", [('prezzo', 'ii:livre|1,6 MILIONI|livre|2 MILIONI'), ('Forse', 'flow:PREZZO INIZIALE?>PREZZO FINALE?')]),
 (11, "Secondo: quanti diamanti, esattamente. Una ricostruzione dice seicentoquarantasette, la reggia di Versailles dice quasi seicentocinquanta. Per questo, in questo video, abbiamo detto quasi seicentocinquanta.", [('Secondo', 'neck:0'), ('seicentoquarantasette', 'ii:diamond|647?|diamond|≈ 650?'), ('quasi', 'stamp:QUASI 650')]),
 (11, "Terzo: la rosa del boschetto. Chi l'ha data a chi? Le fonti non coincidono. E anche il nome del luogo cambia: boschetto della regina, boschetto di Venere.", [('rosa', 'i:rose|CHI A CHI?'), ('luogo', 'grove:0')]),
 (11, "Quarto: la data della consegna della collana, il 25 gennaio o il primo febbraio 1785. E gli anni in cui la collana fu offerta alla regina, che cambiano da una ricostruzione all'altra.", [('consegna', 'ii:calendar_x|25 GENNAIO?|calendar_x|1 FEBBRAIO?'), ('anni', 'i:question|QUALI ANNI?')]),
 (11, "Quinto: il ruolo di Cagliostro. Fu un complice, un consigliere ingenuo del cardinale, o soltanto un nome famoso trascinato dentro? I giudici lo assolsero, e diverse fonti considerano il suo coinvolgimento molto dubbio.", [('ruolo', 'i:flask|COMPLICE?'), ('consigliere', 'iii:handcuffs|COMPLICE?|ear|CONSIGLIERE?|newspaper|SOLO UN NOME?'), ('assolsero', 'stamp:ASSOLTO')]),
 (11, "Sesto: quanti soldi hanno incassato davvero i truffatori vendendo i diamanti, e a chi. Non lo sappiamo con precisione. Di sicuro, non abbastanza da salvarli dal processo.", [('soldi', 'i:moneybag|QUANTO?'), ('precisione', 'i:question|NON SI SA')]),
 (11, "E infine la domanda più grande, quella che si fecero i francesi: la regina sapeva davvero qualcosa? I giudici dell'epoca e gli storici di oggi rispondono di no. Ma all'epoca molti non vollero crederci.", [('domanda', 'i:queen|SAPEVA?'), ('no', 'stamp:NO'), ('crederci', 'crowd')]),
 # 12 LA LEZIONE
 (12, "Questa storia ha più di duecento anni, ma il meccanismo della truffa è sorprendentemente moderno. Lo usano ancora oggi i truffatori che si fingono un direttore, un funzionario, una persona importante.", [('duecento', 'big:> 240 anni|dal boschetto a oggi'), ('meccanismo', 'h:Un meccanismo\n*moderno*'), ('fingono', 'iii:phone|UNA TELEFONATA|envelope|UNA EMAIL|signature|UNA FIRMA')]),
 (12, "Ecco cinque regole che questa storia ci insegna. Prima regola: se qualcuno dice di parlare a nome di una persona importante, verifica direttamente con quella persona, con un canale diverso da quello che ti hanno dato.", [('cinque', 'check:1'), ('verifica', 'flow:UN INTERMEDIARIO>VERIFICA DIRETTA')]),
 (12, "Seconda regola: diffida di chi ti chiede di tenere tutto segreto. Il segreto, nella storia della collana, serviva solo a una cosa: impedire che il cardinale controllasse.", [('Seconda', 'check:2'), ('segreto', 'stamp:IL SEGRETO PROTEGGE IL TRUFFATORE')]),
 (12, "Terza regola: lettere, firme e documenti si possono imitare. Una firma su un foglio non basta a dimostrare chi l'ha scritto, soprattutto se la richiesta è insolita.", [('Terza', 'check:3'), ('firme', 'i:signature|UNA FIRMA NON BASTA')]),
 (12, "Quarta regola: attenzione quando una richiesta tocca il tuo desiderio più forte. Il cardinale voleva così tanto il favore della regina che ha smesso di fare domande. Se una proposta sembra fatta apposta per te, rallenta.", [('Quarta', 'check:4'), ('desiderio', 'i:cardinal|IL SUO DESIDERIO'), ('rallenta', 'stamp:RALLENTA')]),
 (12, "Quinta regola: se pensi di essere caduto in un raggiro, non vergognarti e non aspettare. Rivolgiti subito alle forze dell'ordine e alla tua banca. Il cardinale ha aspettato mesi, e quando ha capito era troppo tardi.", [('Quinta', 'check:5'), ('forze', 'ii:police|FORZE DELL\'ORDINE|bank|LA TUA BANCA'), ('tardi', 'stamp:NON ASPETTARE')]),
 # IL VERDETTO
 (13, "Siamo al verdetto. Riassumiamo questo fascicolo in sei punti.", [('verdetto', 'cover'), ('sei', 'big:6 punti|il riepilogo')]),
 (13, f"Uno: una collana di quasi 650 diamanti, fatta per un re morto nel 1774, resta invenduta per anni. Due: una nobile senza soldi, {JM}, convince un cardinale di essere amica della regina.", [('Uno', 'neck:0'), ('Due', 'ii:lady|JEANNE|cardinal|IL CARDINALE')]),
 (13, "Tre: con lettere false e una sosia nei giardini di Versailles, il cardinale si convince di avere il favore di Maria Antonietta e compra la collana per lei. Quattro: la collana viene smontata, i diamanti venduti tra Parigi e Londra.", [('Tre', 'grove:3'), ('Quattro', 'neck:2')]),
 (13, "Cinque: il 31 maggio 1786 il cardinale, la sosia e il conte di Cagliostro vengono assolti, Jeanne condannata. Sei: la regina, innocente, perde la cosa più preziosa, la reputazione. E Cagliostro finisce i suoi giorni a San Leo.", [('Cinque', 'iii:cardinal|ASSOLTO|lady_white|ASSOLTA|flask|ASSOLTO'), ('Sei', 'i:queen|INNOCENTE'), ('San', 'i:fortress|SAN LEO')]),
 (13, "E ora tocca a te. Secondo te, chi è il vero colpevole di questa storia: chi ha organizzato la truffa, o chi ci ha creduto così facilmente? Scrivilo nei commenti.", [('tocca', 'h:Tocca a *te*'), ('colpevole', 'ii:lady|CHI L\'HA ORGANIZZATA?|cardinal|CHI CI HA CREDUTO?'), ('commenti', 'stamp:SCRIVILO NEI COMMENTI')]),
 (13, "Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.", [('Iscriviti', 'subscribe')]),
]
